namespace JobForFresher.Models;

public sealed record CategoryPreparationSection(string Heading, string Body);
public sealed record CategoryPreparationGuide(string Category, IReadOnlyList<CategoryPreparationSection> Sections)
{
    public string Heading => CategoryGuides.For(Category)!.Heading;
    public string Introduction => CategoryGuides.For(Category)!.Introduction;
    public string Anchor => "guide-" + JobCategories.Slug(Category);
    public DateOnly Updated => new(2026, 9, 30);
}

