    public static CategoryPreparationGuide? For(string? category)
    {
        var name = category?.Trim();
        if (name == null) return null;
        if (Content.TryGetValue(name, out var guide)) return guide;
        var canonical = name.ToLowerInvariant() switch
        {
            "freshers" or "fresher" => "Freshers Jobs",
            "off campus drive" or "off-campus" => "Off Campus",
            "walk-in drive" or "walk in" => "Walk-in",
            "it/software" or "it / software" or "it" => "IT Jobs",
            "government/psu" or "government / psu" or "government" => "Government Jobs",
            "bank" or "banking" => "Bank Jobs",
            "internship" or "internships" => "Internship Programs",
            "wfh jobs" or "remote" or "work from home" => "Work From Home Jobs",
            "mechanical/core" or "mechanical / core" or "core engineering" => "Core Engineering Jobs",
            "bpo" or "support" or "bpo/support" => "BPO / Support Jobs",
            _ => null
        };
        return canonical != null ? Content[canonical] : null;
    }

    public static CategoryPreparationGuide ForJob(Job job) => For(job.Category) ?? For(job.SubCategory) ??
        (job.JobType.Contains("remote", StringComparison.OrdinalIgnoreCase) ? For("Work From Home Jobs") : null) ?? Content["Freshers Jobs"];
}
